"""Stub for feedpin_vendor_sdk - certificate pin validation SDK."""
import hashlib


class PinMismatch(Exception):
    """Raised when certificate fingerprint does not match the pinned value."""
    pass


def fingerprint(cert_der: bytes) -> str:
    """Compute SHA-256 fingerprint from DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """In-memory store of pinned certificate fingerprints per host."""
    _instances = {}

    @classmethod
    def load(cls):
        if not cls._instances:
            cls._instances["default"] = cls()
        return cls._instances["default"]

    def __init__(self):
        self._pins = {
            "feed.marketdata.example": [
                # Pre-computed SHA-256 of b"\x30\x82market-feed-cert"
                "7c29e6b931272787171302e7c66311a70276345c857f00462366825808e7d34e"
            ]
        }

    def matches(self, host: str, fp: str) -> bool:
        """Return True if the fingerprint matches any pin for the given host."""
        known_pins = self._pins.get(host, [])
        return fp in known_pins
